          {/* Left: Code & Console */}
          <div className="flex-1 flex flex-col min-w-0 border-r border-cyber-slate relative">

            {/* Description Box */}
            <div className="p-4 bg-cyber-dark border-b border-cyber-slate">
                <p className="text-sm text-gray-300 leading-relaxed">{currentLevel.description}</p>
                <div className="mt-2 text-xs text-cyber-neon bg-cyber-neon/10 p-2 rounded inline-block border border-cyber-neon/30">
                    <span className="font-bold">OBJECTIVE:</span> {currentLevel.objective}
                </div>
            </div>

            {/* Code Editor */}
            <div className="flex-1 min-h-[300px]">
                <CodeEditor 
                    code={gameState.code} 
                    onChange={(val) => {
                      if (gameState.tutorialPhase === 'IDO') return; // Lock editor during demo
                      setGameState(prev => ({ ...prev, code: val }));
                      resetIdleTimer();
                    }} 
                    readOnly={gameState.tutorialPhase === 'IDO'}
                />
            </div>

            {/* Actions Bar */}
            <div className="h-14 bg-cyber-black border-y border-cyber-slate flex items-center justify-end px-4 gap-3">
                <button 
                    onClick={() => {
                      setGameState(prev => ({...prev, code: currentLevel.initialCode, status: 'idle'}));
                      addLog(MessageType.SYSTEM, "Code reset.");
                    }}
                    disabled={gameState.tutorialPhase === 'IDO'}
                    className="px-4 py-1 text-xs text-gray-500 hover:text-white transition-colors disabled:opacity-30"
                >
                    RESET CODE
                </button>
                <button 
                    onClick={() => handleRunCode(false)}
                    disabled={gameState.status === 'running' || gameState.tutorialPhase === 'IDO'}
                    id="run-button"
                    className={`px-6 py-2 bg-cyber-neon text-black font-bold font-mono text-sm uppercase tracking-wider hover:bg-white hover:shadow-[0_0_15px_#fff] transition-all disabled:opacity-50 disabled:cursor-not-allowed`}
                >
                    {gameState.status === 'running' ? 'EXECUTING...' : 'RUN SCRIPT_'}
                </button>
            </div>

            {/* Console */}
            <div className="h-48">
                <Console logs={gameState.logs} />
            </div>
          </div>

          {/* Right: Visualization & Hints */}
          <div className="w-full md:w-[400px] bg-black flex flex-col">
              <div className="flex-1 relative">
                  <Visualizer level={currentLevel} status={gameState.status} />
              </div>

              {/* Manual Hint Trigger */}
              <div className="h-48 bg-cyber-dark border-t border-cyber-slate p-4 overflow-y-auto">
                  <h3 className="text-xs font-bold text-gray-500 uppercase mb-2">A.D.A.M. Neural Link</h3>
                  <div className="flex gap-3">
                      <button 
                        onClick={() => setActiveHintTier(prev => Math.min(prev + 1, 4))}
                        className="flex-1 border border-gray-700 p-2 rounded hover:bg-gray-800 text-left group"
                      >
                         <div className="text-xs text-cyber-neon mb-1 group-hover:text-white">Request Hint</div>
                         <div className="text-[10px] text-gray-500">Idle Timer: {idleTime}s</div>
                      </button>
                      <button 
                         onClick={() => setActiveHintTier(4)}
                         className="px-3 border border-red-900/50 bg-red-900/10 text-red-500 text-xs rounded hover:bg-red-900/30"
                      >
                        SOS
                      </button>
                  </div>
              </div>
          </div>

        </div>
      </div>
    </div>
  );
};

export default App;
